def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    # Cache stores: key -> (value, write_time)
    cache = OrderedDict()
    results = []

    for op in ops:
        t = op[1]

        # First, remove expired entries
        expired_keys = []
        for key, (value, write_time) in cache.items():
            if write_time + ttl <= t:
                expired_keys.append(key)
        for key in expired_keys:
            del cache[key]

        if op[0] == 'put':
            key, value = op[2], op[3]

            # If key already exists, remove it (will be re-added as most recent)
            if key in cache:
                del cache[key]
            else:
                # Key is absent, check if we need to evict
                if len(cache) >= capacity:
                    # Evict least recently used (first item in OrderedDict)
                    cache.popitem(last=False)

            # Add the new entry (most recently used)
            cache[key] = (value, t)

        elif op[0] == 'get':
            key = op[2]

            if key in cache:
                value, write_time = cache[key]
                results.append(value)
                # Move to end (most recently used)
                del cache[key]
                cache[key] = (value, write_time)
            else:
                results.append(-1)

    return results

